function _ymdSW(d){try{const dt=(d instanceof Date)?d:new Date(d);const p=n=>String(n).padStart(2,'0');return dt.getFullYear()+'-'+p(dt.getMonth()+1)+'-'+p(dt.getDate());}catch(_){return String(d||'').slice(0,10);}}
